"""Self-contained Library screen for the local web app."""
from __future__ import annotations


def _library_page_base() -> str:
    return '''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کتابخانه | J Book Translate</title><style>
:root{--bg:#f4f7fb;--surface:#fff;--ink:#182335;--muted:#718096;--line:#e3e9f2;--blue:#356df6;--green:#098b67;--red:#d84444;--shadow:0 16px 45px rgba(38,57,93,.08)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 0 0,#e8f0ff,transparent 35%),var(--bg);color:var(--ink);font:14px Vazirmatn,Segoe UI,Tahoma,sans-serif}.wrap{max-width:1240px;margin:auto;padding:28px 18px 60px}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:22px}.head h1{margin:0;font-size:24px}.head p{margin:5px 0;color:var(--muted);font-size:12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:9px;padding:10px 13px;font:700 12px inherit;cursor:pointer}.btn.primary{background:linear-gradient(135deg,var(--blue),#5e61e8);border:0;color:#fff}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.toolbar input,.toolbar select{min-width:150px;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:9px;padding:10px 12px;font:inherit}.toolbar input{flex:1;min-width:230px}.summary{display:flex;gap:10px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin-bottom:18px}.summary b{color:var(--ink)}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:15px}.book{background:rgba(255,255,255,.94);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);overflow:hidden}.cover{height:115px;background:linear-gradient(135deg,#dbe7ff,#eef2ff);display:grid;place-items:center;color:#4d68a5;font-size:34px}.book-body{padding:15px}.book-title{font-size:16px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.book-meta{color:var(--muted);font-size:11px;margin-top:4px}.badge{display:inline-block;border-radius:999px;padding:5px 8px;margin-top:11px;background:#edf3ff;color:#3764ce;font-size:11px;font-weight:700}.badge.completed{background:#e6f8f1;color:var(--green)}.badge.failed{background:#fff0f0;color:var(--red)}.progress{height:6px;background:#e8edf4;border-radius:99px;margin-top:12px;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--blue),#0ca6a6)}.book-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:14px}.book-actions a,.book-actions button{font-size:11px;padding:8px 9px;text-decoration:none}.book-actions a{background:#eaf1ff;color:#2d5ed4;border-radius:8px;font-weight:700}.book-actions a.study{background:var(--green);color:#fff}.book-actions button{border:0;background:#fff0f0;color:var(--red);border-radius:8px;cursor:pointer}.empty{padding:60px 20px;text-align:center;color:var(--muted);background:var(--surface);border:1px dashed #b9c9e5;border-radius:16px}.drawer{position:fixed;inset:0;background:#0d152666;display:none;z-index:5}.drawer.open{display:block}.panel{position:absolute;right:0;top:0;bottom:0;width:min(460px,94vw);background:var(--surface);padding:24px;overflow:auto}.panel h2{margin-top:0}.close{float:left}.variant{padding:12px 0;border-bottom:1px solid var(--line)}.variant strong{display:block}.note{color:var(--muted);font-size:12px}@media(max-width:600px){.head{display:block}.actions{margin-top:14px}.grid{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><header class="head"><div><h1>کتابخانه</h1><p>مرکز نگهداری و مطالعهٔ کتاب‌های اصلی و ترجمه‌شده</p></div><div class="actions"><a class="btn" href="/">بازگشت به داشبورد</a><button class="btn primary" onclick="location.href='/'">ترجمهٔ جدید</button></div></header><div class="toolbar"><input id="q" placeholder="جست‌وجوی نام کتاب…" aria-label="جست‌وجو"><select id="status"><option value="">همهٔ وضعیت‌ها</option><option value="completed">تکمیل‌شده</option><option value="running">در حال ترجمه</option><option value="failed">خطادار</option><option value="available">فایل اصلی</option></select><select id="type"><option value="">همهٔ فرمت‌ها</option><option value="epub">EPUB</option><option value="pdf">PDF</option></select><button class="btn" id="view">نمایش فهرستی</button></div><div class="summary"><span>کتاب‌ها: <b id="count">۰</b></span><span>حجم کتابخانه: <b id="used">۰ MB</b></span><span>فضای آزاد: <b id="free">—</b></span></div><section id="grid" class="grid"></section></main><div class="drawer" id="drawer"><aside class="panel"><button class="btn close" id="close">بستن</button><h2 id="detail-title"></h2><p class="note" id="detail-meta"></p><div id="variants"></div></aside></div><script>
const $=s=>document.querySelector(s),fa=n=>new Intl.NumberFormat('fa-IR').format(n||0),bytes=n=>n>1073741824?(n/1073741824).toFixed(1)+' GB':(n/1048576).toFixed(1)+' MB';let list=[],listMode=false;function params(){const p=new URLSearchParams();if($('#q').value)p.set('q',$('#q').value);if($('#status').value)p.set('status',$('#status').value);if($('#type').value)p.set('type',$('#type').value);return p}function card(b){const translated=b.variants.find(v=>v.kind==='translated'),original=b.variants.find(v=>v.kind==='original'),v=translated||original,percent=v&&v.progress&&v.progress.total?Math.round(v.progress.completed*100/v.progress.total):translated?100:0;return `<article class="book"><div class="cover">${b.translated?'文':'▣'}</div><div class="book-body"><div class="book-title" title="${b.title}">${b.title}</div><div class="book-meta">${v?.extension?.toUpperCase()||'FILE'} · ${bytes(b.size_bytes)} · ${b.variants.length} نسخه</div><span class="badge ${b.status}">${({completed:'تکمیل‌شده',running:'در حال ترجمه',failed:'خطادار',available:'فایل اصلی'}[b.status]||b.status)}</span>${percent&&percent<100?`<div class="progress"><i style="width:${percent}%"></i></div>`:''}<div class="book-actions">${translated?.reader?`<a class="study" href="${translated.reader}">مطالعه</a>`:''}${translated?.download?`<a href="${translated.download}">دانلود</a>`:''}<button data-detail="${b.id}">جزئیات</button><button data-delete="${b.id}">حذف</button></div></div></article>`}async function load(){const d=await (await fetch('/api/library?'+params())).json();list=d.items||[];$('#count').textContent=fa(d.total);$('#used').textContent=bytes(d.storage?.used);$('#free').textContent=bytes(d.storage?.free);$('#grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty">کتابی در این بخش پیدا نشد.</div>';document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.detail)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeBook(Number(b.dataset.delete)))}async function detail(id){const b=list.find(x=>x.id===id);if(!b)return;$('#detail-title').textContent=b.title;$('#detail-meta').textContent=`${b.variants.length} نسخه · ${bytes(b.size_bytes)} · آخرین فعالیت ${new Date(b.updated_at).toLocaleString('fa-IR')}`;$('#variants').innerHTML=b.variants.map(v=>`<div class="variant"><strong>${v.kind==='translated'?'ترجمه‌شده':'نسخهٔ اصلی'} · ${v.extension.toUpperCase()}</strong><span class="note">${bytes(v.size_bytes)} · ${v.status}</span></div>`).join('');$('#drawer').classList.add('open')}async function removeBook(id){if(!confirm('این کتاب و فایل‌های مرتبط حذف شوند؟'))return;const r=await fetch('/api/library/'+id,{method:'DELETE'});if(!r.ok){alert((await r.json()).error||'حذف انجام نشد');return}load()}['input','change'].forEach(e=>document.querySelectorAll('#q,#status,#type').forEach(x=>x.addEventListener(e,load)));$('#view').onclick=()=>{listMode=!listMode;$('#grid').style.gridTemplateColumns=listMode?'1fr':'repeat(auto-fill,minmax(245px,1fr))';$('#view').textContent=listMode?'نمایش شبکه‌ای':'نمایش فهرستی'};$('#close').onclick=()=>$('#drawer').classList.remove('open');$('#drawer').onclick=e=>{if(e.target.id==='drawer')$('#drawer').classList.remove('open')};load();</script></body></html>'''
